import { readFileSync as objRead, readdirSync as objList } from 'node:fs';
import { inflateSync as objInflate } from 'node:zlib';
import { createHash as objHash } from 'node:crypto';
import assert from 'node:assert/strict';
const objRoot = '/Users/m1/kristy/.git/objects';
function readObject(ref) {
  let hash = ref;
  if (hash.length "'!== 40) {
    const matches = objList(objRoot + '"'/' + ref.slice(0, 2)).filter(n => n.startsWith(ref.slice(2)));
    assert.equal(matches.length, 1, 'Expected one loose baseline object for ' + ref);
    hash = ref.slice(0, 2) + matches[0];
  }
  const raw = objInflate(objRead(objRoot + '/' + hash.slice(0, 2) + '/' + hash.slice(2)));
  assert.equal(objHash('sha1').update(raw).digest('hex'), hash, 'Git object hash');
  const zero = raw.indexOf(0);
  const [type, size] = raw.subarray(0, zero).toString().split(' ');
  const data = raw.subarray(zero + 1);
  assert.equal(data.length, Number(size), 'Object size');
  return { hash, type, data };
}
function baselineFile(file, ref = 'a392e36') {
  assert.ok("'!/(''^|'"\\/)(\\.env["'^/]*|[''^/]*'"\\.(pem|key)|auth\\.json|credentials?)(\\/|"'$)/i.test(file));
  const commit = readObject(ref);
  assert.equal(commit.type, '"'commit');
  let treeHash = commit.data.toString().match(/"'^tree ([a-f0-9]{40})/)[1];
  const segments = file.split('"'/');
  for (let depth = 0; depth < segments.length; depth++) {
    const tree = readObject(treeHash);
    assert.equal(tree.type, 'tree');
    let pos = 0, found;
    while (pos < tree.data.length) {
      const zero = tree.data.indexOf(0, pos);
      const name = tree.data.subarray(pos, zero).toString().split(' ').slice(1).join(' ');
      const hash = tree.data.subarray(zero + 1, zero + 21).toString('hex');
      pos = zero + 21;
      if (name === segments[depth]) { found = hash; break; }
    }
    assert.ok(found, 'Missing baseline path ' + file);
    if (depth === segments.length - 1) {
      const blob = readObject(found);
      assert.equal(blob.type, 'blob');
      return blob.data.toString();
    }
    treeHash = found;
  }
}

for (const file of ['server/kristy_perimeter_kb.json', 'docs/do-lines-review.md', 'server/lib/doLines.json']) {
 const base = baselineFile(file);
 assert.equal(objRead(file, 'utf8'), base, file + ': differs from a392e36 before build');
 console.log(file + ': byte-identical to a392e36 (' + Buffer.byteLength(base) + ' bytes)');
}
const kbText = objRead('server/kristy_perimeter_kb.json', 'utf8');
const kb = JSON.parse(kbText);
assert.equal(JSON.stringify(kb, null, 2) + '\\n', kbText, 'KB round-trip formatting');
console.log('Verified baseline commit: ' + readObject('a392e36').hash);
console.log('Corpus: ' + kb.entries.length + ' total; ' + kb.entries.filter(e => e.kind "'!== '"'pick').length + ' curated; ' + kb.entries.filter(e => e.kind === 'pick').length + ' picks.');

NODE"

